sections.code:
setp.ge.u32 %p0, %r3, %r4;
@%p0 bra DONE;
// 仅活跃子集执行时不可直接用 0xffffffff 做 shfl.sync
activemask.b32 %r5;
DONE:
ret;

setp.lt.f32 %p0, %f0, 0f00000000;
selp.f32 %f1, 0f00000000, %f0, %p0;   // ReLU 无分支实现
@!%p0 st.global.f32 [%rd0], %f1;

// Producer warp 释放多余寄存器；Consumer warp 申请更多寄存器
setmaxnreg.dec.sync.aligned.u32 40;
// ... Consumer 分支:
setmaxnreg.inc.sync.aligned.u32 232;

// Producer 写入数据后发布标志:
st.global.weak.f32 [%rd_data], %f0;
st.global.release.gpu.u32 [%rd_flag], 1;
// Consumer 等待标志并读取:
POLL:
ld.global.acquire.gpu.u32 %r0, [%rd_flag];
setp.eq.u32 %p0, %r0, 0;
@%p0 bra POLL;
ld.global.weak.f32 %f1, [%rd_data];

cp.async.cg.shared.global [%r_smem], [%rd_gmem], 16;
cp.async.commit_group;
cp.async.wait_group 1;
barrier.sync 0;   // 让同 CTA 其他线程也可见

// 初始化阶段 (单线程 + CTA barrier)
@%p_init mbarrier.init.shared::cta.b64 [%r_mbar], 1;
barrier.sync 0;

// 生产者搬运 (单线程 elect.sync 发射)
elect.sync _|%p_lead, 0xffffffff;
@%p_lead mbarrier.arrive.expect_tx.release.cta.shared::cta.b64 _, [%r_mbar], 4096;
@%p_lead cp.async.bulk.tensor.2d.shared::cta.global.tile.mbarrier::complete_tx::bytes
         [%r_smem], [%rd_tmap, {%r_x, %r_y}], [%r_mbar];

// 消费者等待 (phase_parity = 0, 下一轮用 1 交替)
WAIT_TMA:
mbarrier.try_wait.parity.acquire.cta.shared::cta.b64 %p_done, [%r_mbar], %r_parity;
@!%p_done bra WAIT_TMA;

// 传统蝶形步长 16 -> 1 归约:
shfl.sync.bfly.b32 %f1, %f0, 16, 31, 0xffffffff;
add.f32 %f0, %f0, %f1;
// ... 8, 4, 2, 1 ...
// sm_80+ 整数一步归约:
redux.sync.add.s32 %r_sum, %r_val, 0xffffffff;

// 1. 单线程发射 tcgen05.mma (enable-input-d=%p_accum, 首轮 false 清零累加器)
@%p_lead tcgen05.mma.cta_group::1.kind::f16 [%r_taddr], %rd_adesc, %rd_bdesc, %r_idesc, %p_accum;
// 2. 提交批次至 mbarrier
@%p_lead tcgen05.commit.cta_group::1.mbarrier::arrive::one.shared::cta.b64 [%r_mma_mbar];

// 3. Epilogue warp 等待 MMA 完成 -> fence -> 异步读取 TMEM -> wait::ld
WAIT_MMA:
mbarrier.try_wait.parity.acquire.cta.shared::cta.b64 %p_done, [%r_mma_mbar], %r_parity;
@!%p_done bra WAIT_MMA;
tcgen05.fence::after_thread_sync;
tcgen05.ld.sync.aligned.32x32b.x16.b32 {%r0,%r1,%r2,%r3,%r4,%r5,%r6,%r7,%r8,%r9,%r10,%r11,%r12,%r13,%r14,%r15}, [%r_taddr];
tcgen05.wait::ld.sync.aligned;

.version 8.8
.target sm_103
.address_size 64
.visible .entry vector_add(
 .param .u64 pa, .param .u64 pb, .param .u64 pc, .param .u32 pn
) {
 .reg .pred %p;
 .reg .u32 %r<5>;
 .reg .u64 %rd<8>;
 .reg .f32 %f<3>;
 ld.param.u64 %rd0, [pa];
 ld.param.u64 %rd1, [pb];
 ld.param.u64 %rd2, [pc];
 ld.param.u32 %r4, [pn];
 cvta.to.global.u64 %rd0, %rd0;
 cvta.to.global.u64 %rd1, %rd1;
 cvta.to.global.u64 %rd2, %rd2;
 mov.u32 %r0, %tid.x;
 mov.u32 %r1, %ctaid.x;
 mov.u32 %r2, %ntid.x;
 mad.lo.u32 %r3, %r1, %r2, %r0;
 setp.ge.u32 %p, %r3, %r4;
 @%p bra DONE;
 mul.wide.u32 %rd3, %r3, 4;
 add.u64 %rd4, %rd0, %rd3;
 add.u64 %rd5, %rd1, %rd3;
 add.u64 %rd6, %rd2, %rd3;
 ld.global.f32 %f0, [%rd4];
 ld.global.f32 %f1, [%rd5];
 add.f32 %f2, %f0, %f1;
 st.global.f32 [%rd6], %f2;
DONE:
 ret;
}

.version 8.8
.target sm_103
.address_size 64
.visible .entry reduce256(.param .u64 pa, .param .u64 pout) {
 .reg .pred %p;
 .reg .u32 %r<6>;
 .reg .u64 %rd<4>;
 .reg .f32 %f<2>;
 .shared .align 4 .b8 scratch[1024];
 ld.param.u64 %rd0, [pa];
 ld.param.u64 %rd1, [pout];
 cvta.to.global.u64 %rd0, %rd0;
 cvta.to.global.u64 %rd1, %rd1;
 mov.u32 %r0, %tid.x;
 mul.wide.u32 %rd2, %r0, 4;
 add.u64 %rd3, %rd0, %rd2;
 ld.global.f32 %f0, [%rd3];
 mov.u32 %r1, scratch;
 shl.b32 %r2, %r0, 2;
 add.u32 %r2, %r1, %r2;
 st.shared.f32 [%r2], %f0;
 bar.sync 0;
 mov.u32 %r3, 128;
LOOP:
 setp.ge.u32 %p, %r0, %r3;
 @%p bra WAIT;
 shl.b32 %r4, %r3, 2;
 add.u32 %r5, %r2, %r4;
 ld.shared.f32 %f1, [%r5];
 add.f32 %f0, %f0, %f1;
 st.shared.f32 [%r2], %f0;
WAIT:
 bar.sync 0;
 shr.u32 %r3, %r3, 1;
 setp.ne.u32 %p, %r3, 0;
 @%p bra LOOP;
 setp.ne.u32 %p, %r0, 0;
 @%p bra DONE;
 st.global.f32 [%rd1], %f0;
DONE:
 ret;
}

.version 8.8
.target sm_103
.address_size 64
.visible .entry matmul16(.param .u64 pa, .param .u64 pb, .param .u64 pc) {
 .reg .pred %p;
 .reg .u32 %r<9>;
 .reg .u64 %rd<8>;
 .reg .f32 %f<3>;
 ld.param.u64 %rd0, [pa];
 ld.param.u64 %rd1, [pb];
 ld.param.u64 %rd2, [pc];
 cvta.to.global.u64 %rd0, %rd0;
 cvta.to.global.u64 %rd1, %rd1;
 cvta.to.global.u64 %rd2, %rd2;
 mov.u32 %r0, %tid.x;
 shr.u32 %r1, %r0, 4;
 and.b32 %r2, %r0, 15;
 mov.u32 %r3, 0;
 mov.f32 %f2, 0f00000000;
LOOP:
 mad.lo.u32 %r4, %r1, 16, %r3;
 mad.lo.u32 %r5, %r3, 16, %r2;
 mul.wide.u32 %rd3, %r4, 4;
 mul.wide.u32 %rd4, %r5, 4;
 add.u64 %rd5, %rd0, %rd3;
 add.u64 %rd6, %rd1, %rd4;
 ld.global.f32 %f0, [%rd5];
 ld.global.f32 %f1, [%rd6];
 fma.rn.f32 %f2, %f0, %f1, %f2;
 add.u32 %r3, %r3, 1;
 setp.lt.u32 %p, %r3, 16;
 @%p bra LOOP;
 mul.wide.u32 %rd3, %r0, 4;
 add.u64 %rd7, %rd2, %rd3;
 st.global.f32 [%rd7], %f2;
 ret;
}
